lab=lambda i: ' '.join(k['sentence'] for x in o[i].values() for k in x)
bad=0
for a in A:
    assert a['id'] in o and a['field'] in o[a['id']], (a['id'],a['field'])
    t=re.sub(r'\s+',' ',lab(a['id']))
    if a['evidence'] not in t: print('NOT FOUND',a['id'],a['field']); bad+=1
    for n in re.findall(r'\d+(?:\.\d+)?',a['value']):
        if n not in a['evidence'] and not a['field'].startswith('dial'): print('NUM',a['id'],a['field'],n)
json.dump(A,open('pk_review_v123b.json','w'),ensure_ascii=False,indent=1)
print(len(A),'accepted', bad,'bad')
